Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await BizDb.instance.database;
  runApp(const AfghanBusinessPro());
}

const brand = Color(0xFF087F5B);
const dark = Color(0xFF17352D);
const canvas = Color(0xFFF3F7F5);
String money(num n) => '${n.toStringAsFixed(0)} افغانی';
String dateFmt(Object? v) {
  if (v == null) return '—';
  final d = DateTime.fromMillisecondsSinceEpoch((v as num).toInt());
  return '${d.year}/${d.month.toString().padLeft(2, '0')}/${d.day.toString().padLeft(2, '0')}';
}

