class BizDb {
  BizDb._(); static final instance = BizDb._(); Database? _database;
  Future<Database> get database async {
    if (_database != null) return _database!;
    final root = await getDatabasesPath();
    _database = await openDatabase(p.join(root, 'afghan_business_pro.db'), version: 2,
      onCreate: (db, version) async {
        await db.execute('CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT "",buyPrice REAL NOT NULL DEFAULT 0,sellPrice REAL NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,minStock INTEGER NOT NULL DEFAULT 3,barcode TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE sales(id INTEGER PRIMARY KEY AUTOINCREMENT,invoiceNo TEXT NOT NULL,productId INTEGER NOT NULL,productName TEXT NOT NULL,quantity INTEGER NOT NULL,buyPrice REAL NOT NULL,unitPrice REAL NOT NULL,total REAL NOT NULL,customer TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE debts(id INTEGER PRIMARY KEY AUTOINCREMENT,customer TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",note TEXT NOT NULL DEFAULT "",original REAL NOT NULL,paid REAL NOT NULL DEFAULT 0,createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,category TEXT NOT NULL DEFAULT "عمومی",amount REAL NOT NULL,note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE employees(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",role TEXT NOT NULL DEFAULT "کارمند",salary REAL NOT NULL DEFAULT 0,paid REAL NOT NULL DEFAULT 0,createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",address TEXT NOT NULL DEFAULT "",note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",address TEXT NOT NULL DEFAULT "",note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        await db.execute('CREATE TABLE branches(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,address TEXT NOT NULL DEFAULT "",phone TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
      },
      onUpgrade: (db, oldVersion, newVersion) async {
        if (oldVersion < 2) {
          await db.execute('ALTER TABLE products ADD COLUMN barcode TEXT NOT NULL DEFAULT ""');
          await db.execute('ALTER TABLE sales ADD COLUMN invoiceNo TEXT NOT NULL DEFAULT ""');
          await db.execute('ALTER TABLE sales ADD COLUMN buyPrice REAL NOT NULL DEFAULT 0');
          await db.execute('CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,category TEXT NOT NULL DEFAULT "عمومی",amount REAL NOT NULL,note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
          await db.execute('CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",role TEXT NOT NULL DEFAULT "کارمند",salary REAL NOT NULL DEFAULT 0,paid REAL NOT NULL DEFAULT 0,createdAt INTEGER NOT NULL)');
          await db.execute('CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",address TEXT NOT NULL DEFAULT "",note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
          await db.execute('CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT "",address TEXT NOT NULL DEFAULT "",note TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
          await db.execute('CREATE TABLE IF NOT EXISTS branches(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,address TEXT NOT NULL DEFAULT "",phone TEXT NOT NULL DEFAULT "",createdAt INTEGER NOT NULL)');
        }
      });
    return _database!;
  }
  Future<List<Map<String,Object?>>> rows(String table, {String search = ''}) async {
    const allowed = {'products','sales','debts','expenses','employees','suppliers','customers','branches'};
    if (!allowed.contains(table)) throw Exception('جدول نامعتبر است');
    final db = await database;
    if (search.trim().isEmpty) return db.query(table, orderBy: 'id DESC');
    final fields = switch(table) {
      'products' => 'name LIKE ? OR category LIKE ? OR barcode LIKE ?',
      'sales' => 'productName LIKE ? OR customer LIKE ? OR invoiceNo LIKE ?',
      'debts' => 'customer LIKE ? OR phone LIKE ?',
      'expenses' => 'title LIKE ? OR category LIKE ?',
      'employees' => 'name LIKE ? OR role LIKE ? OR phone LIKE ?',
      'suppliers' || 'customers' => 'name LIKE ? OR phone LIKE ?',
      _ => 'name LIKE ? OR address LIKE ?'
    };
    final count = '?'.allMatches(fields).length;
    return db.query(table, where: fields, whereArgs: List.filled(count, '%${search.trim()}%'), orderBy: 'id DESC');
  }
  Future<int> insert(String table, Map<String,Object?> values) async => (await database).insert(table, {...values,'createdAt':DateTime.now().millisecondsSinceEpoch});
  Future<int> update(String table, int id, Map<String,Object?> values) async => (await database).update(table, values, where:'id=?', whereArgs:[id]);
  Future<int> remove(String table,int id) async => (await database).delete(table,where:'id=?',whereArgs:[id]);
  Future<void> sale({required int productId,required int qty,required String customer,required double price}) async {
    final db=await database;
    await db.transaction((txn) async {
      final list=await txn.query('products',where:'id=?',whereArgs:[productId],limit:1);
      if(list.isEmpty) throw Exception('جنس پیدا نشد');
      final product=list.first; final stock=(product['stock'] as num).toInt();
      if(qty<1 || qty>stock) throw Exception('موجودی کافی نیست');
      final now=DateTime.now(); final invoice='INV-${now.millisecondsSinceEpoch}';
      await txn.update('products',{'stock':stock-qty},where:'id=?',whereArgs:[productId]);
      await txn.insert('sales',{'invoiceNo':invoice,'productId':productId,'productName':product['name'],'quantity':qty,'buyPrice':product['buyPrice'],'unitPrice':price,'total':qty*price,'customer':customer,'createdAt':now.millisecondsSinceEpoch});
    });
  }
  Future<void> repay(int id,double amount) async {
    final db=await database; final r=await db.query('debts',where:'id=?',whereArgs:[id],limit:1); if(r.isEmpty) throw Exception('قرض پیدا نشد');
    final old=(r.first['paid'] as num).toDouble(), original=(r.first['original'] as num).toDouble();
    if(amount<=0 || old+amount>original) throw Exception('مبلغ پرداخت درست نیست');
    await db.update('debts',{'paid':old+amount},where:'id=?',whereArgs:[id]);
  }
  Future<Map<String,num>> stats() async {
    final db=await database;
    Future<num> sum(String sql) async => ((await db.rawQuery(sql)).first.values.first as num);
    return {'products':await sum('SELECT COUNT(*) FROM products'),'stockValue':await sum('SELECT COALESCE(SUM(stock*buyPrice),0) FROM products'),
      'sales':await sum('SELECT COALESCE(SUM(total),0) FROM sales'),'cost':await sum('SELECT COALESCE(SUM(quantity*buyPrice),0) FROM sales'),
      'debts':await sum('SELECT COALESCE(SUM(original-paid),0) FROM debts'),'expenses':await sum('SELECT COALESCE(SUM(amount),0) FROM expenses'),
      'low':await sum('SELECT COUNT(*) FROM products WHERE stock<=minStock'),'employees':await sum('SELECT COUNT(*) FROM employees')};
  }
  Future<void> exportTable(String table) async {
    final data=await rows(table); if(data.isEmpty) throw Exception('برای خروجی گرفتن اطلاعاتی وجود ندارد');
    final keys=data.first.keys.toList(); final csv='\uFEFF${const ListToCsvConverter().convert([keys,...data.map((r)=>keys.map((k)=>r[k]??'').toList()])}';
    final dir=await getTemporaryDirectory(); final file=File(p.join(dir.path,'afghan_business_${table}_${DateTime.now().millisecondsSinceEpoch}.csv'));
    await file.writeAsString(csv,encoding:utf8); await Share.shareXFiles([XFile(file.path)],text:'گزارش افغان بیزنس پرو');
  }
  Future<void> backup() async {
    final db=await database; final source=File(db.path); final dir=await getTemporaryDirectory();
    final file=await source.copy(p.join(dir.path,'afghan_business_backup_${DateTime.now().millisecondsSinceEpoch}.db'));
    await Share.shareXFiles([XFile(file.path)],text:'نسخه پشتیبان اطلاعات افغان بیزنس پرو');
  }
}

