@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.transparent,floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('ثبت قرض')),body:FutureBuilder<List<Map<String,Object?>>>(future:BizDb.instance.rows('debts'),builder:(c,s)=>s.connectionState!=ConnectionState.done?const Center(child:CircularProgressIndicator()):s.data!.isEmpty?const Empty(icon:Icons.account_balance_wallet,title:'قرضی ثبت نشده'):ListView.builder(padding:const EdgeInsets.all(12),itemCount:s.data!.length,itemBuilder:(c,i){final r=s.data![i];final remain=(r['original'] as num)-(r['paid'] as num);return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text('${r['customer']}'),subtitle:Text('اصل قرض: ${money(r['original'] as num)} • پرداخت: ${money(r['paid'] as num)}\nباقی‌مانده: ${money(remain)}'),isThreeLine:true,trailing:remain>0?IconButton(onPressed:()=>repay(r),icon:const Icon(Icons.payments,color:brand),tooltip:'ثبت پرداخت'):const Icon(Icons.check_circle,color:brand)));})));}}

