class RecordList extends StatelessWidget{final String table,title;final IconData icon;final Future<void> Function() onAdd;final List<String> fields;const RecordList({super.key,required this.table,required this.title,required this.icon,required this.onAdd,this.fields=const ['name','phone']});@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.transparent,floatingActionButton:FloatingActionButton.extended(onPressed:onAdd,icon:const Icon(Icons.add),label:Text('ثبت $title')),body:FutureBuilder<List<Map<String,Object?>>>(future:BizDb.instance.rows(table),builder:(c,s)=>s.connectionState!=ConnectionState.done?const Center(child:CircularProgressIndicator()):s.data!.isEmpty?Empty(icon:icon,title:'اطلاعاتی ثبت نشده'):ListView.builder(padding:const EdgeInsets.all(12),itemCount:s.data!.length,itemBuilder:(c,i){final r=s.data![i];return Card(child:ListTile(leading:CircleAvatar(child:Icon(icon)),title:Text('${r[fields[0]]??''}'),subtitle:Text(fields.skip(1).map((f)=>'${r[f]??''}').where((v)=>v.trim().isNotEmpty).join(' • '))));})));}}

class ReportsPage extends StatelessWidget{const ReportsPage({super.key});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(14),children:[const Text('گزارش‌ها و خروجی اطلاعات',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('گزارش CSV را می‌توان در Excel باز کرد.'),for(final entry in const {'products':'اجناس و موجودی','sales':'فروش و فاکتورها','debts':'قرض مشتریان','expenses':'مصارف','employees':'کارمندان','customers':'مشتریان','suppliers':'تأمین‌کنندگان'}.entries)Card(child:ListTile(leading:const Icon(Icons.file_download_outlined,color:brand),title:Text(entry.value),subtitle:const Text('خروجی CSV'),trailing:const Icon(Icons.chevron_left),onTap:()async{try{await BizDb.instance.exportTable(entry.key);}catch(e){if(context.mounted)notice(context,e.toString());}})),const SizedBox(height:12),FutureBuilder<Map<String,num>>(future:BizDb.instance.stats(),builder:(c,s){final m=s.data??{};return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('خلاصه مالی',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),reportLine('مجموع فروش',m['sales']??0),reportLine('بهای خرید اجناس فروخته‌شده',m['cost']??0),reportLine('مصارف ثبت‌شده',m['expenses']??0),reportLine('سود تخمینی', (m['sales']??0)-(m['cost']??0)-(m['expenses']??0)),reportLine('قرض باقی‌مانده',m['debts']??0)])));})]);}
