Widget field(TextEditingController c,String label,{bool num=false})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,keyboardType:num?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,decoration:InputDecoration(labelText:label)));
Future<void> simpleRecordDialog(BuildContext context,{required String title,required List<String> fields,required Future<int> Function(List<String>) save})async{final ctrls=fields.map((_)=>TextEditingController()).toList();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(title),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:List.generate(fields.length,(i)=>field(ctrls[i],fields[i])))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ذخیره'))]));if(ok==true&&ctrls.first.text.trim().isNotEmpty)await save(ctrls.map((e)=>e.text.trim()).toList());}
class Empty extends StatelessWidget{final IconData icon;final String title;const Empty({super.key,required this.icon,required this.title});@override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:54,color:brand.withValues(alpha:.55)),const SizedBox(height:12),Text(title,style:const TextStyle(color:dark,fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('برای شروع از دکمهٔ ثبت استفاده کن.',style:TextStyle(color:Colors.grey))])));}
void notice(BuildContext context,String text)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(text),behavior:SnackBarBehavior.floating));
